\entrytitle{23}{Exact set partition}{strengthPolynomial}{evidencePartial}{hardwareExponential}
\setcounter{problem}{22}
\begin{problem}[Exact set partition]
Given $U$, a nonempty-set family $\mathcal F\subseteq2^U$, and integer $k$, find $S_1,\ldots,S_k\in\mathcal F$ such that $U=S_1\mathbin{\dot\cup}\cdots\mathbin{\dot\cup}S_k$. This is exact cover with a prescribed number of selected sets, and includes many clustering and assignment formulations.
The general comparison uses quantum QRAM time and classical subset-transform time; the explicit-family Boolean bounds count bit operations.
\end{problem}
\speedupheading
\complexity{Quantum}{$O^*((2+c)^{n/2})$ for eligible enumeration base $c<2$, Gaspers--Li partition framework.}
Here $n=|U|$. A restricted-family branching algorithm must enumerate representative members in $O^*(c^{|X|})$ time while preserving a nonstraddling feasible partition. Theorems 5--6 refine the base for small $c$. The complexity includes preprocessing and assumes coherent access to its results; polynomial factors account for membership and feasibility tests.
\complexity{Classical}{$O^*(2^n)$, inclusion--exclusion and subset transforms.}
For an explicit family of $m=\Theta(n)$ sets, selecting exactly one covering set per element and enforcing the chosen cardinality gives a stronger $O_\epsilon(2^{\epsilon n}\operatorname{poly}(n,m))$ bound for each fixed $\epsilon>0$. Long coverage clauses coexist with pairwise incompatibility constraints and a linear-size cardinality circuit. Long-clause shortening and bounded-width counting give the stated time. If the incidence count is linear, a linear-size encoding gives $\operatorname{poly}(n,m)2^{O(n/\sqrt{\log n})}$.
\dimensionlabel{Strength}{strengthPolynomial} Polynomial speedup through a smaller exponential constant for an eligible large or implicit family, from amplitude amplification. Linear-size explicit families have a subexponential classical comparison.
\dimensionlabel{Evidence}{evidencePartial} Rigorous framework theorem under its representative-family hypothesis, with partial evidence against the general classical subset-transform bound.
\dimensionlabel{Hardware}{hardwareExponential} Polynomial active subset and cardinality registers are supplemented by exponential coherent memory. Large-instance fault-tolerant costs also include checking disjointness, membership and total coverage.
\subhead{Algorithm}
\begin{algorithmindex}{23}
\item \href{https://arxiv.org/pdf/2311.08042}{Gaspers and Li, \emph{Quantum Algorithms for Graph Coloring and Other Partitioning, Covering, and Packing Problems} (ICALP 2024)}. Theorem 4: exact-partition framework; Theorems 5--6 and Corollary 1: improved small-$c$ implementation.
\item \href{https://github.com/anthropics/formal-math/tree/main/eth}{Claude (Anthropic), \emph{A $2^{o(n)}$ Time Algorithm for 3-SAT} (2026)}. Long-clause shortening; \href{https://github.com/openai/math/blob/main/preprints/The-Exponential-Time-Hypothesis-is-False-October-25-2026/paper.pdf}{OpenAI, \emph{The Exponential Time Hypothesis Is False}}, Theorem 1.1 and Appendix D, gives the fixed-width contraction routine used after shortening.
\end{algorithmindex}
